3	namespace App\Http\Controllers\Api\Professional\SquareIntegration;
4	
5	use App\Http\Controllers\Api\ApiController;
6	use App\Http\Controllers\Concerns\ResolveCurrentProfessional;
7	use App\Jobs\Square\SyncSquareCatalogDeltaJob;
8	use App\Models\Core\Professional\Professional;
9	use App\Models\Core\Professional\ProfessionalIntegration;
10	use App\Models\Core\Professional\Service;
11	use App\Services\Square\SquareApiException;
12	use App\Services\Square\SquareServiceSyncService;
13	use Illuminate\Http\JsonResponse;
14	use Illuminate\Http\Request;
15	use Illuminate\Support\Facades\Log;
16	
17	// V2: Square POS connection for booking/service sync. Unrelated to V2 commerce — booking integration only.
18	class SquareIntegrationController extends ApiController
19	{
20	    use ResolveCurrentProfessional;
21	
22	    private function currentSquareIntegration(Request $request): ?ProfessionalIntegration
23	    {
24	        $pro = $this->currentProfessional($request);
25	
26	        return $pro->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
27	    }
28	
29	    /**
30	     * Check if the professional has Square connected.
31	     */
32	    private function ensureSquareConnected(Request $request): ?JsonResponse
33	    {
34	        $integration = $this->currentSquareIntegration($request);
35	        if (! $integration) {
36	            return $this->error('Square account not connected.', 404);
37	        }
38	
39	        if (empty($integration->access_token) || empty($integration->external_account_id)) {
40	            return $this->error('Square account not connected.', 404);
41	        }
42	
43	        return null; // Success: connection exists
44	    }
45	
46	    /**
47	     * Build an unsaved ProfessionalIntegration carrying just professional_id +
48	     * provider. Used for connect-style policy checks where no row exists yet.
49	     */
50	    private function squareSkeletonFor(Professional $pro): ProfessionalIntegration
51	    {
52	        return new ProfessionalIntegration([
53	            'professional_id' => $pro->id,
54	            'provider' => ProfessionalIntegration::PROVIDER_SQUARE,
55	        ]);
56	    }
57	
58	    /**
59	     * Build user-friendly error message from Square API exception.
60	     */
61	    private function buildSquareErrorMessage(SquareApiException $e): array
62	    {
63	        $rawMessage = trim($e->getMessage());
64	        $message = $rawMessage !== '' ? $rawMessage : 'Square sync failed.';
65	        $lower = strtolower($message);
66	        $status = $e->status > 0 ? $e->status : 422;
67	
68	        $shouldSuggestReconnect =
69	            str_contains($lower, 'resource not found') ||
70	            str_contains($lower, 'unauthorized') ||
71	            str_contains($lower, 'access token') ||
72	            str_contains($lower, 'merchant');
73	
74	        if ($shouldSuggestReconnect) {
75	            $message .= ' Please reconnect your Square account. If this persists, verify SQUARE_ENVIRONMENT matches the account mode (production vs sandbox).';
76	            $status = 409;
77	        }
78	
79	        return [$message, $status];
80	    }
81	
82	    /**
83	     * GET /api/square/status
84	     * Returns whether the user has Square connected and when it expires.
85	     */
86	    public function status(Request $request)
87	    {
88	        $integration = $this->currentSquareIntegration($request);
89	        $connected = $integration
90	            && ! empty($integration->access_token)
91	            && ! empty($integration->external_account_id);
92	
93	        return $this->success([
94	            'connected' => $connected,
95	            'merchant_id' => $connected ? $integration->external_account_id : null,
96	            'expires_at' => $connected && $integration->expires_at
97	                ? $integration->expires_at->toIso8601String()
98	                : null,
99	        ]);
100	    }
101	
102	    /**
103	     * POST /api/square/connect
104	     * Stores the Square OAuth tokens for this professional.
105	     */
106	    public function connect(Request $request, SquareServiceSyncService $syncService)
107	    {
108	        $request->validate([
109	            'access_token' => 'required|string',
110	            'refresh_token' => 'required|string',
111	            'merchant_id' => 'required|string',
112	            'expires_at' => 'required|string',
113	        ]);
114	
115	        $pro = $this->currentProfessional($request);
116	        $this->authorizeForUser($pro, 'manage', $this->squareSkeletonFor($pro));
117	        $merchantId = trim((string) $request->input('merchant_id'));
118	        if ($merchantId === '') {
119	            return $this->error('merchant_id is required.', 422);
120	        }
121	
122	        $integration = ProfessionalIntegration::query()->updateOrCreate(
123	            [
124	                'professional_id' => $pro->id,
125	                'provider' => ProfessionalIntegration::PROVIDER_SQUARE,
126	            ],
127	            [
128	                'external_account_id' => $merchantId !== '' ? $merchantId : null,
129	                'access_token' => $request->input('access_token'),
130	                'refresh_token' => $request->input('refresh_token'),
131	                'expires_at' => $request->input('expires_at'),
132	                'last_catalog_sync_error' => null,
133	            ]
134	        );
135	
136	        $syncQueued = false;
137	        $syncFallbackInline = false;
138	
139	        // Pull initial services from Square right after connect.
140	        // Prefer async queue, but gracefully fallback to inline if queue infra is unavailable.
141	        try {
142	            SyncSquareCatalogDeltaJob::dispatch((string) $integration->external_account_id, null, true);
143	            $syncQueued = true;
144	        } catch (\Throwable $dispatchError) {
145	            Log::warning('Queue dispatch failed for initial Square sync; falling back inline', [
146	                'professional_id' => $pro->id,
147	                'merchant_id' => $integration->external_account_id,
148	                'message' => $dispatchError->getMessage(),
149	            ]);
150	
151	            try {
152	                $syncService->syncFromSquare($pro, fullSync: true);
153	                $syncFallbackInline = true;
154	            } catch (\Throwable $syncError) {
155	                Log::warning('Initial inline Square sync failed after queue dispatch failure', [
156	                    'professional_id' => $pro->id,
157	                    'merchant_id' => $integration->external_account_id,
158	                    'message' => $syncError->getMessage(),
159	                ]);
160	            }
161	        }
162	
163	        Log::info('Square connected', [
164	            'professional_id' => $pro->id,
165	            'merchant_id' => $integration->external_account_id,
166	        ]);
167	
168	        return $this->success([
169	            'connected' => true,
170	            'merchant_id' => $integration->external_account_id,
171	            'expires_at' => $integration->expires_at?->toIso8601String(),
172	            'sync_queued' => $syncQueued,
173	            'sync_fallback_inline' => $syncFallbackInline,
174	        ]);
175	    }
176	
177	    /**
178	     * POST /api/square/disconnect
179	     * Clears the stored Square tokens for this professional.
180	     */
181	    public function disconnect(Request $request)
182	    {
183	        $pro = $this->currentProfessional($request);
184	        $this->authorizeForUser($pro, 'manage', $this->squareSkeletonFor($pro));
185	        $pro->integrations()
186	            ->where('provider', ProfessionalIntegration::PROVIDER_SQUARE)
187	            ->delete();
188	
189	        Log::info('Square disconnected', [
190	            'professional_id' => $pro->id,
191	        ]);
192	
193	        return $this->success([
194	            'connected' => false,
195	        ]);
196	    }
197	
198	    /**
199	     * GET /api/square/token
200	     * Returns Square integration status (token is kept server-side).
201	     */
202	    public function token(Request $request)
203	    {
204	        if ($error = $this->ensureSquareConnected($request)) {
205	            return $error;
206	        }
207	
208	        $integration = $this->currentSquareIntegration($request);
209	        $pro = $this->currentProfessional($request);
210	        $this->authorizeForUser($pro, 'view', $integration);
211	
212	        return $this->success([
213	            'connected' => $integration?->access_token !== null,
214	            'expires_at' => $integration?->expires_at
215	                ? $integration->expires_at->toIso8601String()
216	                : null,
217	        ]);
218	    }
219	
220	    /**
221	     * POST /api/square/services/sync
222	     * Runs a full pull from Square services into Commet immediately.
223	     * This endpoint is used by the manual refresh button and must work without queue workers.
224	     */
225	    public function syncServicesNow(Request $request, SquareServiceSyncService $syncService)
226	    {
227	        if ($error = $this->ensureSquareConnected($request)) {
228	            return $error;
229	        }
230	
231	        $pro = $this->currentProfessional($request);
232	        $integration = $this->currentSquareIntegration($request);
233	        $this->authorizeForUser($pro, 'manage', $integration);
234	
235	        try {
236	            $stats = $syncService->syncFromSquare($pro, fullSync: true);
237	        } catch (SquareApiException $e) {
238	            [$message, $status] = $this->buildSquareErrorMessage($e);
239	
240	            Log::warning('Manual Square sync failed (Square API)', [
241	                'professional_id' => $pro->id,
242	                'merchant_id' => $integration?->external_account_id,
243	                'status' => $e->status,
244	                'message' => $e->getMessage(),
245	                'payload' => $e->payload,
246	            ]);
247	
248	            return $this->error($message, $status);
249	        } catch (\Throwable $e) {
250	            Log::warning('Manual Square sync failed', [
251	                'professional_id' => $pro->id,
252	                'merchant_id' => $integration?->external_account_id,
253	                'message' => $e->getMessage(),
254	            ]);
255	
256	            return $this->error($e->getMessage(), 422);
257	        }
258	
259	        return $this->success([
260	            'queued' => false,
261	            'synced_inline' => true,
262	            'merchant_id' => $integration?->external_account_id,
263	            'synced' => $stats['synced'] ?? 0,
264	            'deleted' => $stats['deleted'] ?? 0,
265	            'latest_time' => $stats['latest_time'] ?? null,
266	        ]);
267	    }
268	
269	    /**
270	     * POST /api/square/services/{service}/push
271	     * Pushes one local service update to Square immediately.
272	     */
273	    public function pushServiceNow(Request $request, Service $service, SquareServiceSyncService $syncService)
274	    {
275	        $pro = $this->currentProfessional($request);
276	
277	        $this->authorizeForUser($pro, 'view', $service);
278	
279	        if ($error = $this->ensureSquareConnected($request)) {
280	            return $error;
281	        }
282	
283	        $integration = $this->currentSquareIntegration($request);
284	        $this->authorizeForUser($pro, 'manage', $integration);
285	
286	        try {
287	            $syncService->pushServiceToSquare($service, 'upsert');
288	        } catch (\Throwable $e) {
289	            Log::warning('Manual Square push failed', [
290	                'professional_id' => $pro->id,
291	                'service_id' => $service->id,
292	                'message' => $e->getMessage(),
293	            ]);
294	
295	            return $this->error($e->getMessage(), 422);
296	        }
297	
298	        $fresh = Service::query()->withTrashed()->find($service->id);
299	
300	        return $this->success([
301	            'pushed' => true,
302	            'service_id' => $service->id,
303	            'square_catalog_object_id' => $fresh?->square_catalog_object_id,
304	            'square_variation_id' => $fresh?->square_variation_id,
305	            'square_last_synced_at' => $fresh?->square_last_synced_at?->toIso8601String(),
306	            'square_sync_error' => $fresh?->square_sync_error,
307	        ]);
308	    }
309	}
