34	        $integration = $this->currentFreshaIntegration($request);
35	        if (! $integration) {
36	            return $this->error('Fresha account not connected.', 404);
37	        }
38	
39	        if (empty($integration->access_token) || empty($integration->external_account_id)) {
40	            return $this->error('Fresha account not connected.', 404);
41	        }
42	
43	        return null; // Success: connection exists
