58	    /**
59	     * Build user-friendly error message from Fresha API exception.
60	     */
61	    private function buildFreshaErrorMessage(FreshaApiException $e): array
62	    {
63	        $rawMessage = trim($e->getMessage());
64	        $message = $rawMessage !== '' ? $rawMessage : 'Fresha sync failed.';
65	        $lower = strtolower($message);
66	        $status = $e->status > 0 ? $e->status : 422;
67	
68	        $shouldSuggestReconnect =
69	            str_contains($lower, 'resource not found') ||
70	            str_contains($lower, 'unauthorized') ||
71	            str_contains($lower, 'access token') ||
72	            str_contains($lower, 'business');
73	
74	        if ($shouldSuggestReconnect) {
75	            $message .= ' Please reconnect your Fresha account. If this persists, verify FRESHA_ENVIRONMENT matches the account mode (production vs sandbox).';
76	            $status = 409;
77	        }
78	
79	        return [$message, $status];
80	    }
