102	    /**
103	     * POST /api/fresha/connect
104	     * Stores the Fresha OAuth tokens for this professional.
105	     */
106	    public function connect(Request $request, FreshaServiceSyncService $syncService)
107	    {
108	        $request->validate([
109	            'access_token' => 'required|string',
110	            'refresh_token' => 'required|string',
111	            'business_id' => 'required|string',
112	            'expires_at' => 'required|string',
113	        ]);
114	
115	        $pro = $this->currentProfessional($request);
116	        $this->authorizeForUser($pro, 'manage', $this->freshaSkeletonFor($pro));
117	        $businessId = trim((string) $request->input('business_id'));
118	        if ($businessId === '') {
119	            return $this->error('business_id is required.', 422);
120	        }
121	
122	        $integration = ProfessionalIntegration::query()->updateOrCreate(
123	            [
124	                'professional_id' => $pro->id,
125	                'provider' => ProfessionalIntegration::PROVIDER_FRESHA,
126	            ],
127	            [
128	                'external_account_id' => $businessId !== '' ? $businessId : null,
129	                'access_token' => $request->input('access_token'),
130	                'refresh_token' => $request->input('refresh_token'),
131	                'expires_at' => $request->input('expires_at'),
132	                'last_catalog_sync_error' => null,
133	            ]
134	        );
135	
136	        $syncQueued = false;
137	        $syncFallbackInline = false;
138	
139	        // Pull initial services from Fresha right after connect.
140	        // Prefer async queue, but gracefully fallback to inline if queue infra is unavailable.
141	        try {
142	            SyncFreshaCatalogDeltaJob::dispatch((string) $integration->external_account_id, null, true);
143	            $syncQueued = true;
144	        } catch (\Throwable $dispatchError) {
145	            Log::warning('Queue dispatch failed for initial Fresha sync; falling back inline', [
146	                'professional_id' => $pro->id,
147	                'business_id' => $integration->external_account_id,
148	                'message' => $dispatchError->getMessage(),
149	            ]);
150	
151	            try {
152	                $syncService->syncFromFresha($pro, fullSync: true);
153	                $syncFallbackInline = true;
154	            } catch (\Throwable $syncError) {
155	                Log::warning('Inline Fresha sync also failed during connect', [
156	                    'professional_id' => $pro->id,
157	                    'message' => $syncError->getMessage(),
158	                ]);
159	            }
160	        }
161	
162	        Log::info('Fresha connected', [
163	            'professional_id' => $pro->id,
164	            'business_id' => $integration->external_account_id,
165	        ]);
166	
167	        return $this->success([
168	            'connected' => true,
169	            'business_id' => $integration->external_account_id,
170	            'expires_at' => $integration->expires_at
171	                ? $integration->expires_at->toIso8601String()
172	                : null,
173	            'sync_queued' => $syncQueued,
174	            'sync_fallback_inline' => $syncFallbackInline,
175	        ]);
176	    }
