92	                    continue;
93	                }
94	
95	                $itemData = is_array($object['item_data'] ?? null) ? $object['item_data'] : [];
96	                $productType = strtoupper((string) ($itemData['product_type'] ?? ''));
97	                if ($productType !== 'APPOINTMENTS_SERVICE') {
