10	// V2: Square OAuth2 token management with auto-refresh when within 5 minutes of expiration.
11	class SquareTokenService
12	{
13	    public function getAccessToken(Professional $professional): string
14	    {
15	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
16	        if (! $integration) {
17	            throw new SquareApiException('Square access token is missing.');
18	        }
19	
20	        $token = trim((string) ($integration->access_token ?? ''));
21	        if ($token === '') {
22	            throw new SquareApiException('Square access token is missing.');
23	        }
24	
25	        $expiresAt = $integration->expires_at;
26	        if ($expiresAt && $expiresAt->greaterThan(now()->addMinutes(5))) {
27	            return $token;
28	        }
29	
30	        return $this->refreshAccessToken($professional);
31	    }
32	
33	    public function refreshAccessToken(Professional $professional): string
34	    {
35	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_SQUARE);
36	        if (! $integration) {
37	            throw new SquareApiException('Square refresh token is missing.');
38	        }
39	
40	        $refreshToken = trim((string) ($integration->refresh_token ?? ''));
41	        if ($refreshToken === '') {
42	            throw new SquareApiException('Square refresh token is missing.');
43	        }
44	
45	        $clientId = trim((string) config('services.square.application_id', ''));
46	        $clientSecret = trim((string) config('services.square.client_secret', ''));
47	
48	        if ($clientId === '' || $clientSecret === '') {
49	            throw new SquareApiException('Square OAuth credentials are not configured.');
50	        }
51	
52	        $response = Http::acceptJson()
53	            ->asJson()
54	            ->timeout(20)
55	            ->post($this->baseUrl().'/oauth2/token', [
56	                'client_id' => $clientId,
57	                'client_secret' => $clientSecret,
58	                'grant_type' => 'refresh_token',
59	                'refresh_token' => $refreshToken,
60	            ]);
61	
62	        $payload = $response->json();
63	        if (! $response->successful() || ! is_array($payload)) {
64	            throw new SquareApiException(
65	                sprintf('Failed to refresh Square token (HTTP %s).', $response->status()),
66	                $response->status(),
67	                is_array($payload) ? $payload : null
68	            );
69	        }
70	
71	        $accessToken = trim((string) ($payload['access_token'] ?? ''));
72	        if ($accessToken === '') {
73	            throw new SquareApiException('Square token refresh response did not include access_token.');
74	        }
75	
76	        $integration->access_token = $accessToken;
77	        $integration->refresh_token = $payload['refresh_token'] ?? $integration->refresh_token;
78	        $integration->expires_at = isset($payload['expires_at'])
79	            ? CarbonImmutable::parse((string) $payload['expires_at'])
80	            : null;
81	        $integration->save();
82	
83	        return $accessToken;
84	    }
