33	    public function refreshAccessToken(Professional $professional): string
34	    {
35	        $integration = $professional->integrationForProvider(ProfessionalIntegration::PROVIDER_FRESHA);
36	        if (! $integration) {
37	            throw new FreshaApiException('Fresha refresh token is missing.');
38	        }
39	
40	        $refreshToken = trim((string) ($integration->refresh_token ?? ''));
41	        if ($refreshToken === '') {
42	            throw new FreshaApiException('Fresha refresh token is missing.');
43	        }
44	
45	        $clientId = trim((string) config('services.fresha.client_id', ''));
46	        $clientSecret = trim((string) config('services.fresha.client_secret', ''));
47	
48	        if ($clientId === '' || $clientSecret === '') {
49	            throw new FreshaApiException('Fresha OAuth credentials are not configured.');
50	        }
51	
52	        // NOTE: Update this endpoint based on actual Fresha Partner API documentation.
53	        $response = Http::acceptJson()
54	            ->asJson()
55	            ->timeout(20)
56	            ->post($this->baseUrl().'/oauth2/token', [
57	                'client_id' => $clientId,
58	                'client_secret' => $clientSecret,
59	                'grant_type' => 'refresh_token',
60	                'refresh_token' => $refreshToken,
61	            ]);
62	
63	        $payload = $response->json();
64	        if (! $response->successful() || ! is_array($payload)) {
65	            throw new FreshaApiException(
66	                sprintf('Failed to refresh Fresha token (HTTP %s).', $response->status()),
67	                $response->status(),
68	                is_array($payload) ? $payload : null
69	            );
70	        }
71	
72	        $accessToken = trim((string) ($payload['access_token'] ?? ''));
73	        if ($accessToken === '') {
74	            throw new FreshaApiException('Fresha token refresh response did not include access_token.');
75	        }
76	
77	        $integration->access_token = $accessToken;
78	        $integration->refresh_token = $payload['refresh_token'] ?? $integration->refresh_token;
79	        $integration->expires_at = isset($payload['expires_at'])
80	            ? CarbonImmutable::parse((string) $payload['expires_at'])
81	            : null;
82	        $integration->save();
83	
84	        return $accessToken;
85	    }
